/* External CHAT acceptance adapter. No serving changes or source edits. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "chat.h"
static void hex(const unsigned char *p,size_t n){for(size_t i=0;i<n;i++)printf("%02x",p[i]);}
int main(int argc,char**argv){if(argc<5)return 2;CHAT*ch=calloc(1,sizeof(*ch));if(!ch)return 3;ChatInit(ch,argv[1]);ch->episodic.auto_save=0;if(ch->ntfiles!=1||!ch->tgraph||!ch->temb)return 4;size_t capacity=(size_t)strtoul(argv[3],NULL,10);if(!capacity||capacity>16384)return 5;FILE*f=fopen(argv[2],"r");if(!f)return 6;char line[1024],out[16384],slot[CHAT_TOKEN_MAX],family[64];printf("CHAT_ACCEPTANCE_RESULT={\"queries\":[");int first=1;while(fgets(line,sizeof(line),f)){line[strcspn(line,"\r\n")]=0;if(!line[0])continue;if(!first)putchar(',');first=0;ChatParse parsed;memset(&parsed,0,sizeof(parsed));int parse=ChatParseLine(ch,line,&parsed);GoalCause cause;CHAT_CITATION receipt;memset(out,0xa5,sizeof(out));int status;cause=CAUSE_NONE;if(strcmp(argv[4],"resolve")==0)status=ChatResolveLineEx(ch,line,out,capacity,slot,sizeof(slot),family,sizeof(family),&cause,&receipt);else if(strcmp(argv[4],"try")==0){out[0]=0;status=ChatTryTextLineEx(ch,line,out,capacity,&receipt);}else{out[0]=0;status=ChatHandleToBufEx(ch,line,out,capacity,&receipt);}printf("{\"query_hex\":\"");hex((unsigned char*)line,strlen(line));printf("\",\"parse\":%d,\"intent\":\"%s\",\"status\":%d,\"cause\":%d,\"out_hex\":\"",parse,parsed.intent,status,cause);hex((unsigned char*)out,strlen(out));printf("\",\"ntfiles\":%u,\"tnw\":%u,\"ntshown\":%u,\"shown\":[",ch->ntfiles,ch->tnw,ch->ntshown);for(unsigned i=0;i<ch->ntshown;i++)printf("%s%u",i?",":"",ch->tshown[i]);printf("],\"receipt_state\":%d,\"receipt_file\":%u,\"receipt_sentence\":%u,\"receipt_first\":%llu,\"receipt_end\":%llu,\"quote_first\":%zu,\"quote_end\":%zu,\"visible_quote_end\":%zu,\"answer_bytes\":%zu,\"copied_bytes\":%zu,\"output_truncated\":%d,\"display_truncated\":%d,\"evidence\":[",receipt.state,receipt.file_slot,receipt.sentence_index,(unsigned long long)receipt.source.first,(unsigned long long)receipt.source.end,receipt.quote_first,receipt.quote_end,receipt.visible_quote_end,receipt.answer_bytes,receipt.copied_bytes,receipt.output_truncated,receipt.display_truncated);for(unsigned i=0;i<ch->ntshown;i++){uint32_t key=ch->tshown[i],fi=key>>24,si=key&0xffffff;if(i)putchar(',');TL_CITATION c;int valid=fi<ch->ntfiles&&TextLexCitation(&ch->tlex[fi],si,&c)==TL_CITE_OK;printf("{\"file\":%u,\"sentence\":%u,\"valid\":%d",fi,si,valid);if(valid){printf(",\"first\":%llu,\"end\":%llu,\"raw_hex\":\"",(unsigned long long)c.first,(unsigned long long)c.end);hex(ch->tlex[fi].image+c.first,(size_t)(c.end-c.first));putchar('"');}putchar('}');}printf("]}");}printf("]}\n");fclose(f);ChatDestroy(ch);free(ch);return 0;}
